<?php
declare(strict_types=1);
if(function_exists('header_remove'))header_remove('X-Powered-By');
$root=dirname(__DIR__);$configPath=trim((string)(getenv('SOKNA_PUBLIC_CONFIG')?:($root.'/config.php')));
require_once $root.'/src/Core/Config.php';require_once $root.'/src/Core/Database.php';require_once $root.'/src/Emergency/PublicUpdateException.php';require_once $root.'/src/Emergency/EmergencyAccessService.php';require_once $root.'/src/Emergency/PairingSecretStore.php';require_once $root.'/src/Emergency/PublicTakeoverService.php';require_once $root.'/src/Emergency/PublicUpdateService.php';
